is_unrestricted_address(value) {
    lower(trim(value, " \t\n\r")) == unrestricted_addresses[_]
}

# Check if name matches bind keyword (exact match or contains as word)
is_bind_keyword(name) {
    lower_name := lower(name)
    keyword := bind_keywords[_]
    lower_name == keyword
} else {
    lower_name := lower(name)
    keyword := bind_keywords[_]
    contains(lower_name, sprintf("%s_", [keyword]))
} else {
    lower_name := lower(name)
    keyword := bind_keywords[_]
    contains(lower_name, sprintf("_%s", [keyword]))
} else {
    lower_name := lower(name)
    keyword := bind_keywords[_]
    endswith(lower_name, sprintf("%sip", [keyword]))
}

# Exclude Ansible hosts: all false positive
is_hosts_attribute(node) {
    node.ir_type == "Attribute"
    lower(node.name) == "hosts"
}

