get_string_value(node) = value {
    node.ir_type == "String"
    value := node.value
} else = value {
    node.ir_type == "VariableReference"
    value := node.value
}

# Check for unrestricted address in value recursively
has_unrestricted_address(node) {
    walk(node, [_, n])
    n.ir_type == "String"
    is_unrestricted_address(n.value)
}

# Check Hash entry for bind pattern
check_hash_entry(entry) {
    key_str := get_string_value(entry.key)
    is_bind_keyword(key_str)
